  function saveCandidate(id){syncState();if(window.RoleAccessAdminV4&&!RoleAccessAdminV4.can('hrManage'))return;const c=state.candidates.find(x=>x.id===id);if(!c)return;if(!c.employeeId){const values={revision:c.revision||0};for(const k of ['name','email','phone','role','clinic','notes']){const el=$(k==='notes'?'candidateNotes':'candidate'+k[0].toUpperCase()+k.slice(1));if(el)values[k]=el.value.trim()}try{window.CommunicationsV4.updateCandidate(id,values);closeModal();window.V4ClinicHR?.showCandidates()}catch(e){toast(e.message)}return}const oldContract=c.contract,newContract=$('candidateContract').value,before={contract:c.contract,role:c.role,nif:c.nif,niss:c.niss,iban:c.iban,address:c.address,notes:c.notes};c.role=$('candidateRole').value;c.nif=$('candidateNif').value;c.niss=$('candidateNiss').value;c.iban=$('candidateIban').value;c.address=$('candidateAddress').value;c.notes=$('candidateNotes').value;if(oldContract!==newContract){c.contract=newContract;c.documents||=[];for(const d of docsFromContract(newContract))if(!c.documents.some(x=>x.itemId===d.itemId))c.documents.push(d)}c.history.push({at:now(),by:state.currentUser,action:'Ficha atualizada',before,after:{contract:c.contract,role:c.role,nif:c.nif,niss:c.niss,iban:c.iban,address:c.address,notes:c.notes}});audit('RH','Ficha atualizada',c.name);persist();closeModal()}
