  function manageJobRoles(){modal('Funções e cargos',`${state.jobRoles.map(r=>`<div class="task-row"><input id="role_${r.id}" value="${esc(r.name)}"><span class="pill">${r.active?'Ativa':'Inativa'}</span><div><button class="secondary" ${GSSafeActionsV4.attrs("App.saveJobRole",[r.id],"click")}>Guardar</button><button class="danger" ${GSSafeActionsV4.attrs("App.toggleJobRole",[r.id],"click")}>${r.active?'Inativar':'Ativar'}</button></div></div>`).join('')}<div class="actions"><input id="newRole" placeholder="Nova função"><button class="primary" onclick="App.addJobRole()">Adicionar</button></div>`)}
