  function manageContracts(){modal('Tipos de contrato e checklists',`${state.contractTypes.map(ct=>`<div class="card"><div class="actions"><input id="ct_${ct.id}" value="${esc(ct.name)}"><button class="secondary" ${GSSafeActionsV4.attrs("App.saveContract",[ct.id],"click")}>Guardar nome</button><button class="danger" ${GSSafeActionsV4.attrs("App.toggleContract",[ct.id],"click")}>${ct.active?'Inativar':'Ativar'}</button></div>${ct.items.map((i,n)=>`<div class="check"><input id="ci_${ct.id}_${n}" value="${esc(i.name)}"><label><input id="cr_${ct.id}_${n}" type="checkbox" ${i.required?'checked':''}> Obrigatório</label><button class="secondary" ${GSSafeActionsV4.attrs("App.saveContractItem",[ct.id,n],"click")}>Guardar</button></div>`).join('')}<div class="actions"><input id="newItem_${ct.id}" placeholder="Novo documento"><button class="secondary" ${GSSafeActionsV4.attrs("App.addContractItem",[ct.id],"click")}>Adicionar</button></div></div>`).join('')}<div class="actions"><input id="newContract" placeholder="Novo tipo"><button class="primary" onclick="App.addContractType()">Criar tipo</button></div>`)}
  function syncContractDocs(contractId){const ct=state.contractTypes.find(x=>x.id===contractId);state.candidates.filter(c=>c.contract===contractId).forEach(c=>{const existing=new Map((c.documents||[]).map(d=>[d.itemId,d]));for(const i of ct.items.filter(i=>i.active!==false)){const old=existing.get(i.id);if(old)Object.assign(old,{name:i.name,required:i.required});else(c.documents||=[]).push({itemId:i.id,name:i.name,required:i.required,status:'Em falta'})}})} function addContractType(){const name=$('newContract').value.trim();if(!name)return;state.contractTypes.push({id:uid('ct'),name,active:true,items:[]});audit('RH','Tipo de contrato criado',name);persist();manageContracts()}function saveContract(id){const ct=state.contractTypes.find(x=>x.id===id);ct.name=$(`ct_${id}`).value;audit('RH','Tipo de contrato editado',ct.name);persist();manageContracts()}function addContractItem(id){const name=$(`newItem_${id}`).value.trim();if(!name)return;state.contractTypes.find(x=>x.id===id).items.push({id:uid('i'),name,required:true,active:true});syncContractDocs(id);audit('RH','Documento configurado',name);persist();manageContracts()}function saveContractItem(id,n){const i=state.contractTypes.find(x=>x.id===id).items[n];i.name=$(`ci_${id}_${n}`).value;i.required=$(`cr_${id}_${n}`).checked;syncContractDocs(id);audit('RH','Checklist editada',i.name);persist();manageContracts()}function toggleContract(id){const ct=state.contractTypes.find(x=>x.id===id);ct.active=!ct.active;audit('RH','Contrato alterado',ct.name);persist();manageContracts()}
  const markTypes=['Entrada','Saída para almoço','Regresso do almoço','Saída'];
  function todaysEntries(){return state.timeEntries.filter(x=>x.user===state.currentUser&&x.at.slice(0,10)===today()&&markTypes.includes(x.type))}
