  function confirmClockNoGps(type,planned){if(!clockAllowed())return;const u=user(),emp=state.employees?.[u.id]||{},cid=u.clinic||u.clinics?.[0]||emp.clinic||emp.clinics?.[0],base={id:uid('te'),user:state.currentUser,clinic:cid,type,planned,at:now(),geo:'Não exigido'};state.timeEntries.push(base);audit('Ponto','Marcação registada',`${type}; ${base.at}`);persist();closeModal();toast(type+' registada')}
